import{_ as t,o,c as a,a2 as n}from"./chunks/framework.vLhlLNVn.js";const i="/assets/einheit-beheben.DBIukh6F.png",m=JSON.parse('{"title":"Log messages and errors during setup","description":"","frontmatter":{"order":1,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/en/04.fehlerbehebung/01.log-meldungen.md"},"headers":[],"relativePath":"adapter/sourceanalytix/fehlerbehebung/log-meldungen.md","filePath":"adapter/sourceanalytix/fehlerbehebung/log-meldungen.md","lastUpdated":null}'),r={name:"adapter/sourceanalytix/fehlerbehebung/log-meldungen.md"};function s(u,e,l,d,h,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="log-messages-and-errors-during-setup" tabindex="-1">Log messages and errors during setup <a class="header-anchor" href="#log-messages-and-errors-during-setup" aria-label="Permalink to &quot;Log messages and errors during setup&quot;">​</a></h1><p><a id="error-unit-not-supported-no"></a></p><h2 id="unit-not-supported-no-unit-defined-error-–-how-do-i-set-the-unit" tabindex="-1">&quot;unit not supported&quot; / &quot;No unit defined&quot; error – how do I set the unit? <a class="header-anchor" href="#unit-not-supported-no-unit-defined-error-–-how-do-i-set-the-unit" aria-label="Permalink to &quot;&quot;unit not supported&quot; / &quot;No unit defined&quot; error – how do I set the unit?&quot;">​</a></h2><p>SourceAnalytix finds no unit it can calculate with and skips the source. On the &quot;Problems&quot; tab, click &quot;Fix&quot; at &quot;Unit missing or not recognised&quot; and choose the unit the device delivers.</p><p>The log shows <code>No unit defined for &lt;datapoint&gt;, cannot execute calculations !</code>.</p><p>Causes: the object has no unit (common with script datapoints), the unit is spelled out such as <code>Watt</code>, or the quantity is not supported, for example <code>%</code> or <code>h</code>. SourceAnalytix recognises spellings such as <code>m3</code> or <code>kwh</code> itself.</p><p><img src="'+i+'" alt="The &quot;Problems&quot; tab with the &quot;Fix unit&quot; dialog open"></p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Choose the unit the device <strong>delivers</strong>, not the one you want to see. The display unit comes from the price definition. <code>kWh</code> instead of <code>Wh</code> makes all values 1,000 times too large.</p></div><p>If the &quot;Problems&quot; tab instead reports &quot;Unit does not match the price&quot;, say <code>kg</code> and <code>kWh</code>, choose a price definition with a matching unit.</p><p><strong>See also:</strong> <a href="./../referenz/einstellungen#units-supported-energy-volume-weight">Which units are supported?</a> · <a href="./../anleitungen/quellen-und-einheiten#unit-datapoint-kwh-wh-m3">Which unit on the datapoint?</a></p><p><a id="error-known-valueatdevicereset-known-cumulative"></a></p><h2 id="known-valueatdevicereset-known-cumulative-value-error" tabindex="-1">&quot;Known valueAtDeviceReset &gt; known cumulative value&quot; error <a class="header-anchor" href="#known-valueatdevicereset-known-cumulative-value-error" aria-label="Permalink to &quot;&quot;Known valueAtDeviceReset &gt; known cumulative value&quot; error&quot;">​</a></h2><p>The stored offset is greater than the total. The source keeps running anyway, and SourceAnalytix realigns the offset itself with the next value. Check the source&#39;s &quot;Total&quot; afterwards.</p><p>This usually happens when <code>cumulativeReading</code> was lowered or deleted by hand, or when total and settings don&#39;t match after a restore. The message doesn&#39;t occur for power sources.</p><ol><li>Open the source and compare the &quot;Total&quot; with your meter.</li><li>If it doesn&#39;t match, choose &quot;Align meter reading&quot; and enter the reading you took. You can also use &quot;Align&quot; on the &quot;Problems&quot; tab at &quot;Total does not match the meter&quot;.</li></ol><p>The automatic realignment keeps counting from the stored total. If that was set to 0, it starts at 0 until you align it.</p><p><strong>See also:</strong> <a href="./../anleitungen/zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Correcting wrong values</a> · <a href="./falsche-werte-und-bekannte-fehler#after-update-restore-values-0">Values are 0 after a restore</a></p><p><a id="error-no-cost-type-defined"></a></p><h2 id="no-cost-type-defined-error-–-price-definition-missing" tabindex="-1">&quot;No cost type defined&quot; error – price definition missing <a class="header-anchor" href="#no-cost-type-defined-error-–-price-definition-missing" aria-label="Permalink to &quot;&quot;No cost type defined&quot; error – price definition missing&quot;">​</a></h2><p>The source has no price definition. Every source needs one, even if you only want consumption, because it sets the unit. On the &quot;Problems&quot; tab, click &quot;Choose price&quot; and pick one under &quot;Price definition&quot;.</p><p>The &quot;Problems&quot; tab distinguishes two cases:</p><ul><li>&quot;No price definition selected&quot;, in the log <code>No cost type defined for &lt;datapoint&gt; …</code>. This is also the case if you switched the source on at the datapoint on the &quot;Objects&quot; tab.</li><li>&quot;Price definition no longer exists&quot;, in the log <code>Selected Type &lt;name&gt; does not exist in Price Definitions</code>, for example after renaming a category.</li></ul><p>If there is no suitable price yet, create it on the &quot;Price definitions&quot; tab and save. The source starts right after &quot;⚡ Apply&quot;.</p><p><strong>See also:</strong> <a href="./../referenz/einstellungen#price-definition-structured-categories-base">Price definition</a> · <a href="./falsche-werte-und-bekannte-fehler#costs-stay-0-not-calculated">Costs stay 0</a></p><p><a id="messages-initialization-failed-cannot-handle"></a></p><h2 id="initialization-failed-cannot-handle-calculations-reading-incorrect-messages" tabindex="-1">&quot;Initialization failed&quot; / &quot;Cannot handle calculations&quot; / &quot;reading incorrect&quot; messages <a class="header-anchor" href="#initialization-failed-cannot-handle-calculations-reading-incorrect-messages" aria-label="Permalink to &quot;&quot;Initialization failed&quot; / &quot;Cannot handle calculations&quot; / &quot;reading incorrect&quot; messages&quot;">​</a></h2><p>These are summary messages: a source was not started. The cause is in the log lines before it and on the &quot;Problems&quot; tab, which suggests a fix.</p><p>Common causes logged before it:</p><ul><li><code>No unit defined …</code>: see <a href="#error-unit-not-supported-no">Unit missing</a>.</li><li><code>No cost type defined …</code> or <code>Selected Type … does not exist …</code>: see <a href="#error-no-cost-type-defined">Price definition missing</a>.</li><li><code>Unit … cannot be converted …</code> or <code>The data of … is stored in …</code>: unit and price definition don&#39;t match, see <a href="./../anleitungen/quellen-und-einheiten#unit-datapoint-kwh-wh-m3">Changing the unit later</a>.</li><li><code>Cannot use output ID …</code>: the technical ID is invalid or taken, see <a href="./../referenz/einstellungen#name-datapoint-alias-output-id">Name and output ID</a>.</li></ul><p>Once you fix the cause and apply, the source starts without a restart.</p><p>The message <code>reading incorrect after conversion contact DEV</code> should not occur, because text and unsuitable units are caught earlier. If it does appear, report it as an issue with the whole log line.</p><p><strong>See also:</strong> <a href="#datapoint-enabled-but-no-folders">No folders or states</a></p><p><a id="source-delivers-text-instead-number"></a></p><h2 id="source-delivers-text-instead-of-a-number-string-instead-of-number-decimal-point" tabindex="-1">Source delivers text instead of a number (string instead of number, decimal point) <a class="header-anchor" href="#source-delivers-text-instead-of-a-number-string-instead-of-number-decimal-point" aria-label="Permalink to &quot;Source delivers text instead of a number (string instead of number, decimal point)&quot;">​</a></h2><p>SourceAnalytix reads numbers in text itself, with a comma or a dot, for example <code>&quot;12,5&quot;</code>. It skips text with a unit or a thousands separator such as <code>&quot;12,5 kWh&quot;</code>. A datapoint of type number is the safest choice.</p><p>The &quot;Problems&quot; tab then shows &quot;Datapoint delivers text instead of a number&quot;, and the log <code>Value &quot;&lt;value&gt;&quot; of &lt;datapoint&gt; is not a number, reading ignored</code>.</p><ol><li>Check whether the source adapter also offers the value as a number.</li><li>Otherwise, create an alias of type number or a script with <code>parseFloat</code> that converts the text, with the device&#39;s unit.</li><li>Set up the new datapoint with &quot;Add source&quot; and take over the meter reading with &quot;Align meter reading&quot;.</li></ol><p><strong>See also:</strong> <a href="./../anleitungen/quellen-und-einheiten#use-script-datapoints-unreliable-sources">Script datapoints</a></p><p><a id="datapoint-enabled-but-no-folders"></a></p><h2 id="datapoint-enabled-but-no-folders-or-states-appear" tabindex="-1">Datapoint enabled, but no folders or states appear <a class="header-anchor" href="#datapoint-enabled-but-no-folders-or-states-appear" aria-label="Permalink to &quot;Datapoint enabled, but no folders or states appear&quot;">​</a></h2><p>Almost always, SourceAnalytix rejected the source, usually because the price definition or unit is missing. On the &quot;Overview&quot; tab it then has the status &quot;Problem&quot;, and the &quot;Problems&quot; tab shows the reason and the fix.</p><ol><li><strong>Is the instance running?</strong> Otherwise SourceAnalytix doesn&#39;t calculate.</li><li><strong>Is the source listed in the &quot;Overview&quot;?</strong> If not, it is set up for another instance. Create it with &quot;Add source&quot;.</li><li><strong>Status &quot;Deactivated&quot;?</strong> Choose &quot;Activate&quot; on the source.</li><li><strong>Status &quot;Problem&quot;?</strong> The button on the &quot;Problems&quot; tab fixes it or takes you to the right place.</li><li><strong>Is &quot;Consumption&quot; on?</strong> Without the tick, no consumption values are created.</li></ol><p>Once the source runs, the folder <code>sourceanalytix.0.&lt;device&gt;</code> appears immediately, and the values with the datapoint&#39;s next value. If the folder is missing on the &quot;Objects&quot; tab, reload the view and check the filters.</p><p><strong>See also:</strong> <a href="./../erste-schritte/erster-zaehler#configure-sourceanalytix-datapoint">Where do I configure SourceAnalytix?</a></p><p><a id="high-cpu-memory-use-too"></a></p><h2 id="high-cpu-and-memory-load-and-too-much-log-output" tabindex="-1">High CPU and memory load and too much log output <a class="header-anchor" href="#high-cpu-and-memory-load-and-too-much-log-output" aria-label="Permalink to &quot;High CPU and memory load and too much log output&quot;">​</a></h2><p>SourceAnalytix calculates with every new value of every source. Load mainly comes from sources that send very often. For less log output, set the instance to the &quot;warn&quot; level.</p><ul><li>Set a longer send interval in the source adapter, if possible.</li><li>Use a meter reading instead of power if the device delivers both.</li><li>Pause sources you don&#39;t need with &quot;Deactivate&quot;.</li></ul><p>You set the log level on the &quot;Instances&quot; tab in expert mode. If another adapter floods the log, that adapter&#39;s log level helps.</p><p><strong>See also:</strong> <a href="#object-limit-warning-5000">Object limit</a></p><p><a id="installation-admin-display-problems"></a></p><h2 id="problems-with-installation-and-the-admin-display" tabindex="-1">Problems with installation and the Admin display <a class="header-anchor" href="#problems-with-installation-and-the-admin-display" aria-label="Permalink to &quot;Problems with installation and the Admin display&quot;">​</a></h2><p>Install from the &quot;latest&quot; repository, not from GitHub, and check the <a href="./../erste-schritte/installation#requirements-sourceanalytix-have-node-js">requirements</a>. If something is still missing in Admin, upload the files again with <code>iobroker upload sourceanalytix</code>.</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Fix</th></tr></thead><tbody><tr><td>GitHub installation fails with 404 or 422</td><td>update js-controller or install from &quot;latest&quot;</td></tr><tr><td>no instance under &quot;Instances&quot;</td><td>create the instance</td></tr><tr><td><code>Cannot load jsonConfig of sourceanalytix: Not exists</code></td><td><code>iobroker upload sourceanalytix</code>, reload the page</td></tr><tr><td>&quot;Overview&quot; empty, &quot;Instance is not running&quot;</td><td>start the instance, &quot;Try again&quot;</td></tr><tr><td>&quot;not maintained&quot;</td><td>comes from a GitHub installation, has no effect</td></tr><tr><td>Multihost: &quot;admin not found&quot;</td><td>install or update Admin on that host</td></tr></tbody></table><p><strong>See also:</strong> <a href="./../erste-schritte/installation#install-sourceanalytix-create-instance">Installation</a> · <a href="./../anleitungen/betrieb-und-wartung#update-sourceanalytix-downgrade">Update</a></p><p><a id="midnight-crash-rollover-wrong-time"></a></p><h2 id="midnight-crash-or-day-rollover-at-the-wrong-time" tabindex="-1">Midnight: crash or day rollover at the wrong time <a class="header-anchor" href="#midnight-crash-or-day-rollover-at-the-wrong-time" aria-label="Permalink to &quot;Midnight: crash or day rollover at the wrong time&quot;">​</a></h2><p>The rollover runs at 0:00 by the system time of the ioBroker host. If it comes at the wrong hour, the time zone there is wrong. A crash with <code>ENOENT</code> at midnight is caused by js-controller when it switches the log file; SourceAnalytix catches up the missed rollover by itself afterwards.</p><p>If ioBroker runs in Docker on UTC, the day changes at 1:00 or 2:00 in Central Europe. Set the environment variable <code>TZ=Europe/Berlin</code> (or your own zone) and restart the container.</p><p>If a rollover is missing, the &quot;Problems&quot; tab shows &quot;Period rollover missed&quot; with &quot;Recover&quot;, see <a href="./../anleitungen/betrieb-und-wartung#iobroker-was-down-midnight-recover">ioBroker was off at midnight</a>.</p><p><a id="object-limit-warning-5000"></a></p><h2 id="object-limit-warning-5000" tabindex="-1">Object limit warning (5000) <a class="header-anchor" href="#object-limit-warning-5000" aria-label="Permalink to &quot;Object limit warning (5000)&quot;">​</a></h2><p>The warning comes from js-controller; SourceAnalytix itself has no limit. Every source creates many states. First check what you need:</p><ul><li>Turn off period options you don&#39;t use under &quot;Main settings&quot;.</li><li>Delete sources you no longer need with &quot;Delete data&quot;.</li><li>Delete old year folders.</li></ul><p>If the number is intended, you can raise the limit in expert mode on the object <code>system.adapter.sourceanalytix.0</code>.</p><p><strong>See also:</strong> <a href="./../referenz/einstellungen#instance-settings-exist-periods-decimals">Instance settings</a></p><p><a id="source-adapter-history-shows-0"></a></p><h2 id="source-adapter-or-history-shows-0-or-old-values" tabindex="-1">Source adapter or history shows 0 or old values <a class="header-anchor" href="#source-adapter-or-history-shows-0-or-old-values" aria-label="Permalink to &quot;Source adapter or history shows 0 or old values&quot;">​</a></h2><p>Usually nothing arrives at the source datapoint any more. SourceAnalytix only reads it and never writes its value; a 0 in the source datapoint&#39;s history comes from the adapter or a script.</p><p>If the source adapter renamed its datapoints, SourceAnalytix keeps listening to the old one:</p><ol><li>Check &quot;Last update&quot; on the source. If the old datapoint was deleted, the &quot;Problems&quot; tab reports &quot;Datapoint no longer exists&quot;.</li><li>Create the new datapoint with &quot;Add source&quot; and take over the reading with &quot;Align meter reading&quot;.</li><li>Point VIS and scripts to the new folder. The old one stays as an archive.</li></ol>',71)])])}const g=t(r,[["render",s]]);export{m as __pageData,g as default};
